/**
 * layers/cl/mop.js — Capas del MOP Chile
 *
 * Ministerio de Obras Públicas — https://rest-sit.mop.gob.cl/arcgis/rest/services
 * Catálogo completo: 342 capas. Protocolo: ArcGIS REST (MapServer / FeatureServer)
 *
 * Keywords: manuales + automáticas desde valores_unicos del catálogo.
 * Convenciones:
 *  - Keys con sufijo _cl para consistencia entre países.
 *  - special: false            → capa general de uso público
 *  - special: 'historico'      → datos de períodos pasados
 *  - special: 'cartografico'   → capas de base cartográfica/referencia
 *  - special: 'administrativo' → contratos, proyectos internos MOP
 *  - special: 'auxiliar'       → capas de soporte sin valor semántico directo
 *  - special: 'operacional'    → datos operacionales de concesionarias
 *  - special: 'tecnico'        → datos técnicos/sectoriales de uso específico
 *  - visible: true  → se muestra por defecto en el catálogo de la UI
 *  - visible: false → disponible para el LLM, oculta en la UI por defecto
 */

