    tituloUI:     'Servicios Sanitarios Rurales',
    abstract:     'Cobertura de puntos que representan la ubicación aproximada de los Servicio Sanitario Rural la simbología representa la clasificación de los operadores de Servicios Sanitarios Rurales, conforme a lo dispuesto en el artículo 106 del Reglamento de la Ley 20.998 y artículo 70 de la Ley. Artículo 106.\n\nSimbología Oficial: Obedece a Clasificación por tamaño del Sistema según artículo 106 del Reglamento de la Ley 20.998 donde Punto azul para los de tamaño Mayor, Punto Rojo para Mediano, Punto verde para Menor y Punto Amarillo para sin solicitud de Clasificación. \n\nCorresponde a información de la Dirección de Obras Hidráulicas del Ministerio de Obras Públicas.\n\nLa información que fue levantada por personal de la Subdirección de Servicios Sanitarios Rurales donde corresponde a levantamiento georreferenciado con el Sistema Global de Navegación por Satélite GNSS (métrico) de los estanques, oficina o localidad beneficiada, o trazado en Google Earth o similar.\n\nEstos archivos son considerados documentos de trabajo y corresponden a Bases de Datos dinámicas que están en constante depuración, complementación y actualización. Por lo cual se puede considerar como la última información disponible.\n\nLa información aquí contenida de libre uso para la ciudadanía. En caso de utilizar sin alterar los datos, se debe mención con fuente de Dirección de Obras Hidráulicas del Ministerio de Obras Públicas \n\nLink del documento con metadata https://docs.google.\ncom/document/d/1a7C6pxZ3t1QNwm5q4tsQB59KrvJVAqmZ/edit',
