    abstract:     'Servicio de ArcGIS Server10.2 con geometrías de puntos que representan emergencias ocurridas sobre la infraestructura del Ministerio de Obras Públicas.\nSe incluyen Emergencias en: Agua Potable Rural, Obras Portuarias, Obras Aeroportuarias, Riego, Cauce, Aguas Lluvias, Estaciones DGA, Edificación Pública y Vialidad.\nLas emergencias se clasifican en tres niveles según el grado de operación que tiene la obra afectada. Se clasifica en: Operativo, Parcialmente Operativo y No Operativo.\nLos eventos de emergencias se registran en un sistema de Gestión denominado SIEMOP y se georreferencian en la IDE, manteniendo conexión entre sus atributos a través de procesos de interoperabilidad, por lo tanto, la actualización de la data está ligada al mantenimiento reportado en el sistema de gestión.\nLa información está referida al Sistema SIRGAS CHILE, con coordenadas Geográficas.',
