  ILOG_INFRA_ILOG_MapServer_2_cl: {
    source:       'mop_cl',
    srs:          'EPSG:4326',
    typename:     'ILOG/INFRA_ILOG/MapServer/2',
    featureCount:  450,
    titulo:       'Infraestructura Vial ILOG',
    tituloUI:     'Infraestructura Vial (ILOG)',
    abstract:     'AtributosDescripción:ROLRol del camino de acuerdo con la normativa vigente. Puede ser por Resolución exenta o Decreto Supremo, cuando corresponda. Los caminos en proceso de enrolamiento, en este campo llevan un Rol propuesto antecedido por S/R-.ROL_ID_REGIONALDados ciertos geo-procesos que se requieren aplicar, es necesario tener una columna con un identificador único a nivel regional. Considerando que el ROL es un valor que se usa para identificar los caminos, y a pesar de que la idea es tener un solo registro por rol, hay más de uno por diferentes motivos; se ha definido crear un campo llamado ROL_ID, donde se diferenciarán los roles en cada región, agregándoles un correlativo, generando así el ID regional requerido.CALZADAValor que permite identificar si la calzada es única o doble y si es doble si es la izquierda o la derecha.ORIENTACIONLa información contenida en este campo diferencia los caminos que tienen más de un kilómetro cero (0,000) en cuanto a su ubicación u orientación (Norte, Sur, Este, Oeste, Centro y Única para el caso de los caminos con un único Km 0,000).ROL_LABELCorresponde al valor que tendrá la etiqueta del Rol de los caminos en un mapa; solo llevan valor los registros de caminos enrolados.CODIGO_CAMINOCorresponde a la codificación interna de la Dirección de Vialidad, corresponde al Código del Activo Camino.El código tiene la siguiente estructura 12$34567; donde 12 es el código de la Región; $ es la letra correspondiente a la clasificación de caminos (DS 301 de 2011 y DS 436 de 2014) para caminos enrolados o su equivalente para los caminos declarados Públicos en Zona Urbana por Decreto Supremo que se encuentren completos dentro de dicha área y para el caso de los caminos por enrolar les corresponde la letra S; 3 corresponde a la Provincia (similar al Código Único Territorial del INE) y 4567 al número del rol.Todos los registros deben tener valor, de no existir se pondrá guion (-).NOMBRE_CAMINONombre del camino.Todos los registros deben tener valor, de no existir se pondrá guion (-).CLASIFICACIONClasificación de caminos según DS 301 de 2011 y DS 436 de 2014para el caso de caminos enrolados o su equivalente para el caso de caminos por enrolar y Caminos declarados públicos en Zona Urbana.Todos los registros deben tener valor, de no existir se pondrá “Sin Información”.CARPETA Corresponde al tipo de material de rodados que se utilizó para el acabado en la construcción del camino.Contiene los siguientes tipos de carpeta:- Pavimento Doble Calzada: Hormigón o Asfalto en doble calzada.- Pavimento: Hormigón o Asfalto- Pavimento Básico: Carpetas de rodadura con capas de protección asfálticas.- Grava Tratada: Carpeta de rodadura de agregado pétreo estabilizados con soluciones en base a sales o con productos químicos, entre otros.- Ripio: Carpeta de rodadura de agregado pétreo.- Suelo Natural.Existen registros con la categoría “Sin Información”, los cuales están en proceso de actualización.KM_IKilometraje de inicio del segmento de camino al que corresponda el registro, expresado en metros.Campo cuyo valor se obtiene automáticamente desde la polilínea y corresponde al valor de la coordenada M del primer vértice. Todos los registros deben tener valor, de no existir quedará un 0 (cero).KM_FKilometraje de término del segmento de camino al que corresponda el registro, expresado en metros.Campo cuyo valor se obtiene automáticamente desde la polilínea y corresponde al valor de la coordenada M del último vértice.Todos los registros deben tener valor, de no existir quedará un 0 (cero).KM_TRAMOLongitud del segmento de camino al que corresponda el registro, expresado en metros.Campo cuyo valor se obtiene restando los valores de los campos KM_F y KM_I.Todos los registros deben tener valor, de no existir quedaráun 0 (cero).ENROLADOEste campo indica si el registro corresponde a un camino o tramo de camino enrolado o no. Todos los registros deben tener un valor, si no se ha hecho la revisión, el valor será: “Sin Revisar”.CONCESIONADOEste campo indica si el registro corresponde a un camino o tramo de camino concesionado o no. Todos los registros deben tener un valor, si no se ha hecho la revisión, el valor será: “Sin Revisar”.REGIONIndica el nombre de la Región donde está el camino. Todos los registros deben tener valor.',
    geomType:     'line',
    clipStrategy: 'spatial',
    special:      'auxiliar',
    visible:      false,
    keywords:     ['camino nacional', 'camino nacional longitudinal', 'camino regional comunal', 'camino regional de acceso', 'camino regional principal', 'camino regional provincial', 'grava tratada', 'pavimento', 'pavimento basico', 'pavimento doble calzada', 'ripio', 'suelo natural'],
    attributes: [
      { campo: 'ROL', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'CODIGO_CAMINO', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'NOMBRE_CAMINO', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'CLASIFICACION', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'CARPETA', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'KM_I_NEW', labelEn: '', label: '', tipo: 'int', visible: true },
      { campo: 'KM_F_NEW', labelEn: '', label: '', tipo: 'int', visible: true },
      { campo: 'ENROLADO', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'CONCESIONADO', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'REGION', labelEn: '', label: '', tipo: 'string', visible: true },
      { campo: 'SHAPE_STLength__', labelEn: '', label: '', tipo: 'decimal', visible: true },
      { campo: 'SHAPE.STLength()', labelEn: '', label: '', tipo: 'decimal', visible: true }
    ]
  },

