    tituloUI:     'Puentes (Vialidad — duplicado)',
    abstract:     'Cobertura de puntos que representa la ubicación y contiene la descripción de los puentes, viaductos y pasos superiores de tuición de la Dirección de Vialidad del MOP a nivel nacional. \nDefinición técnica Activo de obra de infraestructura pública: Puentes: Son las obras viales destinadas a permitir la continuidad de un camino de uso público sobre obstáculos naturales, tales como ríos, mar, esteros, lagos, etc. En este tipo de activos, se deben distinguir claramente una superestructura y una infraestructura. \nViaductos: Son las obras viales destinadas a permitir la continuidad de un camino de uso público sobre hondonadas (quebradas, farellones, etc.). En este tipo de activos, se deben distinguir claramente una superestructura y una infraestructura.\nPasos Superiores: Son las obras viales destinadas a permitir la continuidad de un camino de uso público sobre  vías férreas o carreteras. En este tipo de activos, se deben distinguir claramente una superestructura y una infraestructura.\nDefinición de Tipología de Activos de Infraestructura Vial para normas NIC-SP.\nCorresponde a información de la Dirección de Vialidad del Ministerio de Obras Públicas.\nLa fuente es mayormente levantamiento georreferenciado con el Sistema Global de Navegación por Satélite GNSS. \nEscala estimada de precisión 1:5.000\n',
