    tituloUI:     'Red Vial Estructurante',
    abstract:     'La Red Vial Estructurante (RVE) es una capa que identifica los caminos que proveen de mayor conectividad a los centros poblados y enclaves productivos del país y que, por tanto, implica prioridad en su materialización en los diversos proyectos o contratos viales a los largo de Chile. El formato dispuesto para visualizar esta información es Geodatabase como polilínea y se encuentra actualizada con el último estudio RVE existente (2021).\n\nLa Dirección de Vialidad del Ministerio de Obras Públicas, a través de su Departamento de Planes de Infraestructura Vial de la Subdirección de Desarrollo; estimó necesaria la Actualización de la Red Vial Estructurante de Chile, en la perspectiva de avanzar en el proceso de planificación y priorización de las intervenciones sobre la vialidad del país.',
